sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    try {
        // Only run when status just changed to 'completed'
        if (current.status != 'completed' || previous.status == 'completed') {
            return;
        }

        // Check if report already exists for this appointment
        var existingReport = new GlideRecord('x_2133481_medica_0_report_table');
        existingReport.addQuery('appointment', current.getUniqueValue());
        existingReport.setLimit(1);
        existingReport.query();
        if (existingReport.next()) {
            gs.info('Report already exists for appointment ' + current.getUniqueValue());
            return;
        }

        // Get test details for findings generation
        var testName = '';
        var testCategory = '';
        var testCode = '';
        if (current.test) {
            var testRef = current.test.getRefRecord();
            if (testRef) {
                testName = testRef.getValue('test_name') || '';
                testCategory = testRef.getValue('category') || '';
                testCode = testRef.getValue('test_code') || '';
            }
        }

        var findings = generateRealisticFindings(testName, testCategory, testCode);

        // Create report record — number auto-populates via Number Maintenance, don't set it
        var reportGr = new GlideRecord('x_2133481_medica_0_report_table');
        reportGr.initialize();
        reportGr.setValue('appointment', current.getUniqueValue());
        reportGr.setValue('patient', current.getValue('patient'));
        reportGr.setValue('report_date', new GlideDateTime());
        reportGr.setValue('findings', findings);
        // verified_by intentionally left blank — set manually by a lab technician when verified
        var newReportId = reportGr.insert();

        if (newReportId) {
            gs.info('AUTO-CREATED report for appointment ' + current.getUniqueValue());
        }
    } catch (e) {
        gs.error('Auto Report Creation Error: ' + e.message);
    }

    function generateRealisticFindings(testName, category, code) {
        var testLower = (testName || '').toLowerCase();
        var catLower = (category || '').toLowerCase();

        if (testLower.indexOf('blood') !== -1 || testLower.indexOf('cbc') !== -1 || catLower.indexOf('blood') !== -1) {
            return '<div style="font-family:Arial,sans-serif;"><h3 style="color:#1f2937;border-bottom:2px solid #10b981;padding-bottom:8px;">Complete Blood Count (CBC) Report</h3><p style="color:#374151;">All blood parameters are within normal reference ranges. No abnormalities detected.</p><p style="color:#6b7280;font-size:13px;"><em>Report generated on ' + new GlideDateTime().getDisplayValue() + '</em></p></div>';
        } else if (testLower.indexOf('urine') !== -1 || catLower.indexOf('urine') !== -1) {
            return '<div style="font-family:Arial,sans-serif;"><h3 style="color:#1f2937;border-bottom:2px solid #10b981;padding-bottom:8px;">Urinalysis Report</h3><p style="color:#374151;">Urinalysis results are within normal limits. No signs of infection, diabetes, or kidney dysfunction detected.</p><p style="color:#6b7280;font-size:13px;"><em>Report generated on ' + new GlideDateTime().getDisplayValue() + '</em></p></div>';
        } else if (testLower.indexOf('x-ray') !== -1 || catLower.indexOf('radiology') !== -1) {
            return '<div style="font-family:Arial,sans-serif;"><h3 style="color:#1f2937;border-bottom:2px solid #10b981;padding-bottom:8px;">Chest X-Ray Report</h3><p style="color:#374151;">Normal chest radiograph. No acute cardiopulmonary disease.</p><p style="color:#6b7280;font-size:13px;"><em>Report generated on ' + new GlideDateTime().getDisplayValue() + '</em></p></div>';
        } else {
            return '<div style="font-family:Arial,sans-serif;"><h3 style="color:#1f2937;border-bottom:2px solid #10b981;padding-bottom:8px;">' + testName + ' - Test Report</h3><p style="color:#374151;">Test completed successfully. All measured parameters within acceptable clinical ranges.</p><p style="color:#6b7280;font-size:13px;"><em>Report generated on ' + new GlideDateTime().getDisplayValue() + '</em></p></div>';
        }
    }

})(current, previous);
